class.description:
Classe statique : on ne l'instancie pas, on appelle directement ses méthodes. Chaque personnage s'y inscrit à son entrée dans l'arbre et en sort à sa sortie (en jeu uniquement, pas dans l'éditeur). Les distances sont des distances euclidiennes complètes (hauteur comprise en 3D, y compris en vue de côté en 2D), contrairement à [method Character2D.planar_distance_to].
[codeblock]
# Tourelle (script sur un Character2D de faction « defense ») : vise l'ennemi vivant le plus proche.
extends Character2D

func _physics_process(_delta: float) -> void:
	var cible := CharacterRegister.get_nearest(self, 400.0, true)
	if cible:
		$Canon.look_at(cible.global_position)
[/codeblock]
